def test_format_phone_another_number():
    """Test another 10-digit number."""
    result = format_phone("9876543210")
    assert result == "(987) 654-3210", f"Expected '(987) 654-3210', got '{result}'"


def test_format_phone_rejects_spaces():
    """Test that spaces in input raise ValueError."""
    try:
        format_phone("123 456 7890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_rejects_country_code():
    """Test that country code prefix raises ValueError."""
    try:
        format_phone("11234567890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_rejects_short():
    """Test that fewer than 10 digits raises ValueError."""
    try:
        format_phone("123456789")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_rejects_non_string():
    """Test that non-string input raises TypeError."""
    try:
        format_phone(1234567890)
        assert False, "Should have raised TypeError"
    except TypeError:
        pass


def test_format_phone_rejects_separators():
    """Test that separators in input raise ValueError."""
    try:
        format_phone("123-456-7890")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_rejects_non_digits():
    """Test that non-digit characters raise ValueError."""
    try:
        format_phone("123456789a")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_format_phone_all_zeros():
    """Test all zeros format correctly."""
    result = format_phone("0000000000")
    assert result == "(000) 000-0000", f"Expected '(000) 000-0000', got '{result}'"


def test_format_phone_all_nines():
    """Test all nines format correctly."""
    result = format_phone("9999999999")
    assert result == "(999) 999-9999", f"Expected '(999) 999-9999', got '{result}'"
"}

